// Independent re-acquisition of official CR PDFs; compares SHA-256 with RULE-01 recorded values (audit only).
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
const recorded = JSON.parse(readFileSync('docs/rules/2026-10-10-sources.json', 'utf8')).sources;
const want = Object.fromEntries(recorded.filter(r => ['cr-2.2', 'cr-2.3', 'resources'].includes(r.id)).map(r => [r.id, r]));
let ok = true;
for (const id of ['cr-2.2', 'cr-2.3']) {
  const r = want[id];
  const res = await fetch(r.url, { signal: AbortSignal.timeout(60000) });
  const buf = Buffer.from(await res.arrayBuffer());
  const sha = createHash('sha256').update(buf).digest('hex');
  const match = sha === r.sha256 && buf.length === r.bytes;
  ok &&= match && res.ok && buf.subarray(0, 5).toString() === '%PDF-';
  console.log(`${id} http=${res.status} bytes=${buf.length} sha256=${sha} recorded_match=${match}`);
}
const page = await (await fetch(want.resources.url, { signal: AbortSignal.timeout(60000) })).text();
const linked = page.includes('CRUpdate_EN_Oct-2026.pdf');
const linked22 = page.includes('Comprehensive-Rules_2.2.0-EN.pdf');
console.log(`resources page links CRUpdate_EN_Oct-2026.pdf=${linked} Comprehensive-Rules_2.2.0-EN.pdf=${linked22} (page bytes change over time; hash not compared)`);
ok &&= linked;
console.log(ok ? 'PASS independent re-acquisition' : 'FAIL independent re-acquisition');
process.exitCode = ok ? 0 : 1;
